-- 090 — Script de dados (rodar uma vez, DEPOIS de publicar o site com public/fotos-genericas/).
-- Gerado de _shared/foto-generica.ts (mesmas regras do generate-article).
-- Retroativo: foto genérica de assessoria nas matérias de segurança/esportes sem foto (30 dias)
with alvo as (
  select g.id, case
      when c.slug = 'seguranca' and translate(lower(g.titulo || ' ' || coalesce(g.resumo,'')), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc') ~ '\y(incendio|pegou fogo|fogo (em|atinge|destroi|destruiu)|chamas|bombeir|siate|resgat|afoga|soterr|desabamento|desabou|deslizamento|correnteza)' then array[(array['bombeiros-1'])[1 + abs(hashtext(g.id::text)) % 1], (array['Foto: Henrique Vieira/Sesp'])[1 + abs(hashtext(g.id::text)) % 1], (array['Viaturas do Corpo de Bombeiros do Paraná (imagem de arquivo)'])[1 + abs(hashtext(g.id::text)) % 1]]
      when c.slug = 'seguranca' and translate(lower(g.titulo || ' ' || coalesce(g.resumo,'')), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc') ~ '\y(rodovias?\y|prc?-?\d{3}|estrada|engavet|blitz|lei seca)' then array[(array['rodovia-1','rodovia-2','rodovia-3'])[1 + abs(hashtext(g.id::text)) % 3], (array['Foto: Polícia Rodoviária do Paraná','Foto: Polícia Rodoviária do Paraná','Foto: Polícia Rodoviária do Paraná'])[1 + abs(hashtext(g.id::text)) % 3], (array['Viatura da Polícia Rodoviária Estadual (imagem de arquivo)','Fiscalização da Polícia Rodoviária Estadual (imagem de arquivo)','Motociclistas da Polícia Rodoviária Estadual (imagem de arquivo)'])[1 + abs(hashtext(g.id::text)) % 3]]
      when c.slug = 'seguranca' and translate(lower(g.titulo || ' ' || coalesce(g.resumo,'')), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc') ~ '\y(acidente de transito|colisao|colidi|capot|atropel|tomba|batida entre|motociclista|motoboy)' then array[(array['pm-viatura-1','pm-viatura-2','pm-viatura-3'])[1 + abs(hashtext(g.id::text)) % 3], (array['Foto: Rodrigo Félix Leal/AEN','Foto: Rodrigo Félix Leal/AEN','Foto: Rodrigo Félix Leal/AEN'])[1 + abs(hashtext(g.id::text)) % 3], (array['Viaturas da Polícia Militar do Paraná (imagem de arquivo)','Viaturas da Polícia Militar do Paraná (imagem de arquivo)','Viaturas da Polícia Militar do Paraná (imagem de arquivo)'])[1 + abs(hashtext(g.id::text)) % 3]]
      when c.slug = 'seguranca' and translate(lower(g.titulo || ' ' || coalesce(g.resumo,'')), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc') ~ '\y(pericia|perito|iml|necropsia|cientifica|corpo (e |foi )?encontrado|ossada|cadaver)' then array[(array['cientifica-1'])[1 + abs(hashtext(g.id::text)) % 1], (array['Foto: Sesp'])[1 + abs(hashtext(g.id::text)) % 1], (array['Viaturas da Polícia Científica do Paraná (imagem de arquivo)'])[1 + abs(hashtext(g.id::text)) % 1]]
      when c.slug = 'seguranca' and translate(lower(g.titulo || ' ' || coalesce(g.resumo,'')), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc') ~ '\y(presidio|penitenciar|cadeia publica|detento|custodiad|policia penal|depen|rebeliao|fuga de presos|sistema prisional)' then array[(array['penal-1'])[1 + abs(hashtext(g.id::text)) % 1], (array['Foto: Geraldo Bubniak/AEN'])[1 + abs(hashtext(g.id::text)) % 1], (array['Viaturas da Polícia Penal do Paraná (imagem de arquivo)'])[1 + abs(hashtext(g.id::text)) % 1]]
      when c.slug = 'seguranca' and translate(lower(g.titulo || ' ' || coalesce(g.resumo,'')), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc') ~ '\y(delegacia|delegad[oa]|inquerito|policia civil|pcpr|investigac|indiciad|mandado de prisao|golpe|estelionat)' then array[(array['civil-1','civil-2'])[1 + abs(hashtext(g.id::text)) % 2], (array['Foto: PCPR','Foto: PCPR'])[1 + abs(hashtext(g.id::text)) % 2], (array['Delegacia da Polícia Civil do Paraná (imagem de arquivo)','Delegacia da Polícia Civil do Paraná (imagem de arquivo)'])[1 + abs(hashtext(g.id::text)) % 2]]
      when c.slug = 'seguranca' and translate(lower(g.titulo || ' ' || coalesce(g.resumo,'')), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc') ~ '\y(policia|pm\y|policiais|policial|rotam|bpfron|prend|preso|presa|prisao|flagrante|furt|roub|assalt|homicid|assassin|tiro|disparo|arma|droga|trafic|apreen|abordag|agred|agress|ameac|violencia|crime|suspeit|facad|esfaque)' then array[(array['pm-viatura-1','pm-viatura-2','pm-viatura-3'])[1 + abs(hashtext(g.id::text)) % 3], (array['Foto: Rodrigo Félix Leal/AEN','Foto: Rodrigo Félix Leal/AEN','Foto: Rodrigo Félix Leal/AEN'])[1 + abs(hashtext(g.id::text)) % 3], (array['Viaturas da Polícia Militar do Paraná (imagem de arquivo)','Viaturas da Polícia Militar do Paraná (imagem de arquivo)','Viaturas da Polícia Militar do Paraná (imagem de arquivo)'])[1 + abs(hashtext(g.id::text)) % 3]]
      when c.slug = 'esportes' and translate(lower(g.titulo || ' ' || coalesce(g.resumo,'')), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc') ~ '\y(coritiba|couto pereira)\y' then array[(array['couto-pereira-1'])[1 + abs(hashtext(g.id::text)) % 1], (array['Foto: Geraldo Bubniak/AEN'])[1 + abs(hashtext(g.id::text)) % 1], (array['Estádio Couto Pereira, em Curitiba (imagem de arquivo)'])[1 + abs(hashtext(g.id::text)) % 1]]
      else null end as f
  from generated_articles g join editorial_categories c on c.id = g.categoria_id
  where g.status = 'publicado' and g.imagem_capa_url is null and c.slug in ('seguranca','esportes')
    and g.publicado_em > now() - interval '30 days'
    and not (c.slug = 'seguranca' and (translate(lower(g.titulo || ' ' || coalesce(g.resumo,'')), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc') ~ '\y(estupr|abuso sexual|infantojuvenil|pedofil|maus-tratos|vulneravel)' or translate(lower(g.titulo || ' ' || coalesce(g.resumo,'')), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc') ~ '\y(policia federal|pf\y|receita federal|gaeco|prf\y|policia rodoviaria federal|br-?\d{3})'))
)
update generated_articles g set
  imagem_capa_url = 'https://vozesparanaenses.com.br/fotos-genericas/' || a.f[1] || '.jpg',
  og_image_url = 'https://vozesparanaenses.com.br/fotos-genericas/' || a.f[1] || '.jpg',
  imagem_credito = a.f[2], imagem_legenda = a.f[3], foto_origem = 'generica_institucional'
from alvo a where a.id = g.id and a.f is not null
returning g.titulo, a.f[1];
